import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    """
    Compresses all files in the source folder using gzip and moves them to the destination folder.
    Each compression is initiated as a background process.

    Args:
        src_folder (str): Path to the source directory.
        dst_folder (str): Path to the destination directory.

    Returns:
        dict: A dictionary containing 'success', 'message', and 'failed_files'.
    """
    # Ensure destination folder exists
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except Exception as e:
            return {
                'success': False,
                'message': f"Failed to create destination directory: {str(e)}",
                'failed_files': []
            }

    # Identify all files in the source folder
    file_paths = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]

    if not file_paths:
        return {
            'success': True,
            'message': "No files found in the source folder to compress.",
            'failed_files': []
        }

    # List to track background processes: (original_file_path, process_object)
    running_processes = []
    failed_files = []

    # Start compression for each file as a background process
    for fpath in file_paths:
        try:
            # gzip <file> creates <file>.gz and removes the original file by default
            # subprocess.Popen runs the command in the background
            p = subprocess.Popen(['gzip', fpath], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            running_processes.append((fpath, p))
        except Exception:
            failed_files.append(os.path.basename(fpath))

    # Wait for processes to complete and move the resulting .gz files
    for fpath, p in running_processes:
        fname = os.path.basename(fpath)
        try:
            # Wait for the specific background process to finish
            p.wait()

            if p.returncode == 0:
                gz_filename = fname + '.gz'
                src_gz_path = fpath + '.gz'
                dst_gz_path = os.path.join(dst_folder, gz_filename)

                # Verify the compressed file exists before moving
                if os.path.exists(src_gz_path):
                    shutil.move(src_gz_path, dst_gz_path)
                else:
                    failed_files.append(fname)
            else:
                failed_files.append(fname)
        except Exception:
            failed_files.append(fname)

    success = len(failed_files) == 0
    if success:
        message = "All files were compressed and moved successfully."
    else:
        message = f"Operation completed with errors. Failed to process {len(failed_files)} file(s)."

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

